// src/pages/MovieDetail.jsx
import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { moviesData } from '../data/moviesData';

function MovieDetail() {
  const { id } = useParams(); // URL 파라미터에서 영화 ID 가져오기
  const movie = moviesData[id] || moviesData["ratatouille"]; // 데이터가 없으면 기본값

  return (
    <div className="w-full min-h-screen bg-[#0b090e] text-white flex flex-col items-center pb-20">
      
      {/* 상단 히어로/배경 영역 */}
      <div className="w-full relative h-[450px] flex flex-col justify-end p-8 bg-cover bg-center" style={{ backgroundImage: `url(${movie.backdrop})` }}>
        <div className="absolute inset-0 bg-gradient-to-t from-[#0b090e] via-transparent to-black/60" />
        <div className="relative z-10 max-w-4xl w-full mx-auto space-y-2">
          <h1 className="text-4xl md:text-6xl font-black tracking-tight">{movie.title}</h1>
          <p className="text-xs text-zinc-300 font-bold">
            {movie.year} | {movie.age} | {movie.duration} | Language: {movie.language}
          </p>
        </div>
      </div>

      {/* 중단 정보 및 포스터 틀 영역 */}
      <div className="max-w-4xl w-full px-6 -mt-10 relative z-20 grid grid-cols-1 md:grid-cols-3 gap-8 items-start">
        
        {/* 포스터 */}
        <div className="w-48 h-72 rounded-xl overflow-hidden shadow-2xl border border-white/10 mx-auto md:mx-0">
          <img src={movie.poster} alt={movie.title} className="w-full h-full object-cover" />
        </div>

        {/* 상세 설명 (틀) */}
        <div className="md:col-span-2 space-y-4 bg-[#181124]/80 backdrop-blur-md p-6 rounded-2xl border border-purple-500/20">
          <div>
            <span className="text-xs text-purple-400 font-bold uppercase">Directed by</span>
            <p className="text-sm font-bold text-white">{movie.director}</p>
          </div>

          <p className="text-xs text-zinc-300 leading-relaxed">
            {movie.synopsis}
          </p>

          <div className="flex gap-2 pt-2">
            {movie.genres?.map((genre, idx) => (
              <span key={idx} className="text-[10px] font-bold px-3 py-1 rounded-full border border-purple-400/40 text-purple-200">
                {genre}
              </span>
            ))}
          </div>

          {/* 평점 원형 틀 */}
          <div className="flex items-center justify-between pt-4 border-t border-white/10">
            <span className="text-xs font-bold text-zinc-400">Rating Score</span>
            <div className="w-12 h-12 rounded-full border-2 border-yellow-400 flex items-center justify-center text-yellow-400 font-black text-sm">
              {movie.rating}
            </div>
          </div>
        </div>

      </div>

      {/* 갤러리 섹션 틀 */}
      <div className="max-w-4xl w-full px-6 mt-12">
        <h3 className="text-sm font-black tracking-widest text-purple-300 mb-4 uppercase">Gallery</h3>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {movie.gallery?.map((img, idx) => (
            <div key={idx} className="h-36 rounded-xl overflow-hidden border border-white/10 shadow-lg">
              <img src={img} alt="gallery" className="w-full h-full object-cover hover:scale-105 transition duration-300" />
            </div>
          ))}
        </div>
      </div>

      {/* 다른 영화로 넘어가는 네비게이션 링크 예시 */}
      <div className="flex gap-4 mt-12">
        <Link to="/movie/ratatouille" className="px-4 py-2 bg-purple-600 rounded-lg text-xs font-bold">라따뚜이 보기</Link>
        <Link to="/movie/grandma" className="px-4 py-2 bg-purple-600 rounded-lg text-xs font-bold">할머니 영화 보기</Link>
      </div>

    </div>
  );
}

export default MovieDetail;
